def header(doc):
    t = doc.add_table(rows=4, cols=4)
    t.alignment = WD_TABLE_ALIGNMENT.CENTER
    borders(t)
    cell_text(t.cell(0, 0).merge(t.cell(0, 3)),
              '國立高雄科技大學_金屬中心_日報', 14, True)
    cell_text(t.cell(1, 0), '時間')
    cell_text(t.cell(1, 1), '2026/08/20')
    cell_text(t.cell(1, 2), '學生')
    cell_text(t.cell(1, 3), '李承育')
    cell_text(t.cell(2, 0), '地點')
    cell_text(t.cell(2, 1).merge(t.cell(2, 3)),
              '金屬中心（獨立驗證、方法邊界檢視與交付物更新）')
    cell_text(t.cell(3, 0).merge(t.cell(3, 3)), '內容與過程註記')
    for r in t.rows:
        r.cells[0].width = Mm(22)
    return t


def rich(doc, text, indent=8, after=4, size=12):
    """以 ** 標記行內粗體。範本標題用粗體、內文偶爾強調，兩者都需要。"""
    p = doc.add_paragraph()
    for i, seg in enumerate(text.split('**')):
        if seg:
            style_run(p.add_run(seg), size, bold=(i % 2 == 1))
    pf = p.paragraph_format
    pf.space_before = Pt(0)
    pf.space_after = Pt(after)
    pf.left_indent = Mm(indent)
    pf.line_spacing = Pt(20)
    return p


def sec(doc, label, title):
    para(doc, '%s %s' % (label, title), 12, True, before=10, after=4)


def band(doc, title):
    """待辦事項／補充：範本作滿版橫幅，此處以單格表格取得同樣的框線。"""
    t = doc.add_table(rows=1, cols=1)
    t.alignment = WD_TABLE_ALIGNMENT.CENTER
    borders(t)
    cell_text(t.cell(0, 0), title, 12, True, center=False)
    para(doc, '', 4)


