def main():
    doc = Document()
    s = doc.sections[0]
    s.page_width, s.page_height = Mm(210), Mm(297)
    s.left_margin = s.right_margin = Mm(25)
    s.top_margin = s.bottom_margin = Mm(20)
    st = doc.styles['Normal']
    st.font.name = EN
    st.font.size = Pt(12)
    st.element.rPr.rFonts.set(qn('w:eastAsia'), CN)

    header(doc)
    para(doc, '', 6)
    para(doc, '執行項目', 12, True, after=4)
    for it in ITEMS:
        para(doc, it, 12, indent=8, after=2)
    para(doc, '執行內容如下所示：', 12, True, before=8, after=4)

    sec(doc, '1.', '甲烷化學計量對帳')
    for t in S1:
        rich(doc, t)
    para(doc, S1EQ, 12, indent=16, after=4)
    for t in S1B:
        rich(doc, t)
    data_table(doc, ['批次', '循環時間', 'n', 'CH4/消耗', '生物份額'],
               [['一', '1 分', '6', '0.2172', '87%'],
                ['二', '5 分', '10', '0.1682', '67%'],
                ['三', '10 分', '14', '0.1928', '77%']],
               [22, 26, 18, 32, 28])
    for t in S1C:
        rich(doc, t)

    sec(doc, '2.', '莫耳速率換算')
    for t in S2:
        rich(doc, t)

    sec(doc, '3.', '論文估計器於三批次之正面對照')
    for t in S3:
        rich(doc, t)
    data_table(doc, ['批次', '逐段中位', '四分位', '化學計量', '差'],
               [['一（1 分）', '0.01344', '0.01213 / 0.01485', '0.01610',
                 '+20%'],
                ['二（5 分）', '0.01896', '−0.07205 / 0.02259', '0.02920',
                 '+54%'],
                ['三（10 分）', '−0.03057', '−0.09977 / 0.01682', '0.02810',
                 '—']], [26, 26, 44, 26, 18])
